CREATE POLICY "Published portfolio media readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'portfolio-media' AND EXISTS (SELECT 1 FROM public.content_entries e WHERE e.image_url = name AND e.published));
CREATE POLICY "Admins upload portfolio media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'portfolio-media' AND private.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins edit portfolio media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'portfolio-media' AND private.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'portfolio-media' AND private.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins remove portfolio media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'portfolio-media' AND private.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins view draft portfolio media" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'portfolio-media' AND private.has_role(auth.uid(), 'admin'));